import shutil

from pyspark.sql import functions as F

spark.conf.set("spark.sql.adaptive.enabled", "false")

ARCHIVE = "/tmp/archive/trips"

QUERIES = [
    "payment_type = 'cash'",
    "payment_type <> 'cash'",
    "payment_type IS NULL",
    "payment_type = 'no_charge'",
    "total >= 20",
    "payment_type = 'card' AND total >= 20",
    "payment_type = 'card' OR total >= 60",
]


def write_archive(trips):
    # partitionBy writes one folder per payment type (payment_type=card/ ...); trips with no type get a folder too.
    shutil.rmtree(ARCHIVE, ignore_errors=True)
    trips.write.partitionBy("payment_type").option("header", True).csv(ARCHIVE)


def read_archive(schema):
    return spark.read.schema(schema).option("header", True).csv(ARCHIVE)


def profile(df):
    """Run df once, then list the plan steps Spark ran with the counts it kept."""
    df.collect()
    labels = {"numOutputRows": "rows", "shuffleRecordsWritten": "shuffled rows", "numFiles": "files", "filesSize": "bytes"}
    steps = []

    def walk(node, depth):
        name = node.nodeName().strip()
        if name == "AdaptiveSparkPlan":
            return walk(node.executedPlan(), depth)
        if name.endswith("QueryStage"):
            return walk(node.plan(), depth)
        metrics = node.metrics()
        counts = {label: metrics.apply(key).value() for key, label in labels.items() if metrics.contains(key)}
        if counts:
            steps.append(("  " * depth + name, counts))
            depth += 1
        children = node.children()
        for i in range(children.size()):
            walk(children.apply(i), depth)

    walk(df._jdf.queryExecution().executedPlan(), 0)
    return steps


def files_and_rows(archive, query):
    # How many files the query's scan opens, and how many rows the query returns.
    return 0, 0


def solve(trips):
    write_archive(trips)
    archive = read_archive(trips.schema)
    rows = [(query, *files_and_rows(archive, query)) for query in QUERIES]
    return spark.createDataFrame(rows, "query STRING, files LONG, rows LONG")
